-- GERADO por scripts/acj-build-library.mjs — definições ACJ-01..05 (v0.1, em validação).
-- A tabela guarda o necessário para seleção, validação, rastreabilidade e analytics;
-- o texto completo continua nos .md (document_ref).
INSERT INTO public.acj_definitions (acj_id, version, status, name, short_phrase, purpose, desired_effect, primary_question,
  state_from, state_to, mechanism, color, editorial_hints, data, document_ref, effective_from)
VALUES
  ('ACJ-01', '0.1', 'in_validation', 'Reconhecimento', 'Eu vejo.', 'Tornar visível e nomeável algo que já está acontecendo.', 'É isso. Agora consigo ver e nomear.', 'O que precisa tornar-se visível e nomeável para que a jornada possa começar ou recomeçar?',
   'realidade difusa, normalizada, fragmentada ou ainda sem linguagem', 'realidade percebida, nomeada e disponível para investigação', 'revelação orientada por distinção, nomeação e enquadramento', '#D4A017', ARRAY['diagnostico-sistemico','provocacao-de-crenca','case-anonimizado']::text[], '{"id":"ACJ-01","name":"Reconhecimento","version":"0.1","status":"in_validation","document_ref":"docs/acj/ACJ-01_Reconhecimento_v0.1.md","primary_question":"O que precisa tornar-se visível e nomeável para que a jornada possa começar ou recomeçar?","state_from":"realidade difusa, normalizada, fragmentada ou ainda sem linguagem","state_to":"realidade percebida, nomeada e disponível para investigação","mechanism":"revelação orientada por distinção, nomeação e enquadramento","central_phrase":"antes de se mover em uma jornada, a audiência precisa poder ver o que até então permanecia difuso, naturalizado ou sem nome.","definition":"Reconhecimento é a arquitetura que torna perceptível e nomeável uma realidade relevante ainda difusa, fragmentada, naturalizada ou mal compreendida pela audiência. Seu movimento ocorre quando o conteúdo distingue sinais, revela relações e oferece linguagem suficiente para que algo passe de sensação ou ruído a objeto consciente de atenção. Ela não exige que a pessoa já se reconheça pessoalmente naquela realidade, confie no produtor, experimente algo ou queira aprofundar-se. Seu resultado essencial é mais elementar: “agora consigo ver e nomear o que está sendo apontado”.","purposes":["revelar fenômenos, tensões, padrões ou possibilidades ainda pouco percebidos","organizar sinais dispersos em uma leitura inteligível","oferecer linguagem para algo que era apenas sentido, repetido ou normalizado","deslocar explicações simplistas quando elas impedem uma leitura mais ampla","estabelecer um objeto comum de atenção a partir do qual outras ACJs possam operar","abrir curiosidade e disponibilidade para investigar, sem forçar identificação, vínculo ou ação"],"indications":["a audiência sente efeitos, mas ainda não percebe o padrão que os conecta","uma realidade foi normalizada e deixou de ser interrogada","os sinais existem, mas aparecem fragmentados ou atribuídos apenas a causas individuais","a campanha introduz uma lente, um paradigma ou uma distinção ainda pouco familiar","existe vocabulário insuficiente para nomear a experiência","a conversa pública está presa a uma explicação superficial","é necessário criar um ponto de entrada para pessoas em diferentes estágios da jornada","a audiência avançou anteriormente, mas precisa reconhecer uma nova camada, tema ou contexto"],"preconditions":["apontar uma realidade observável ou uma hipótese explicitamente apresentada como tal","distinguir fatos, interpretações e inferências","oferecer linguagem clara sem empobrecer a complexidade","apresentar sinais, relações, exemplos ou evidências suficientes para sustentar o enquadramento","preservar espaço para que a audiência observe antes de concordar","manter coerência com os princípios, o repertório e o lugar de fala de Marcos e da Bee"],"contraindications":["a realidade já está claramente percebida e a necessidade é a pessoa localizar-se nela","a principal lacuna é confiança, reciprocidade ou qualidade de vínculo","a audiência precisa experimentar uma nova possibilidade, não apenas compreendê-la","já existe prontidão para integração, continuidade ou aprofundamento","a situação exige orientação prática imediata","o produtor não possui base suficiente para nomear a realidade sem especulação excessiva","a ideia depende de medo, choque ou exagero para parecer relevante"],"timing":["no início de campanhas que introduzem uma nova leitura de realidade","antes de conceitos complexos, ofertas ou experiências que exigem repertório prévio","quando a campanha alcança novos segmentos ou amplia distribuição","em momentos de mudança externa que tornam um padrão novamente relevante","depois de saturação narrativa, quando é preciso revelar outra camada do mesmo fenômeno","em reentradas, quando pessoas conhecidas encontram a jornada por um novo tema"],"mechanism_steps":{"origin":"A pessoa percebe efeitos, desconfortos, acontecimentos ou possibilidades, mas ainda não os organiza em uma realidade inteligível.","operation":"O produtor dirige a atenção para sinais e relações relevantes, oferecendo distinção, linguagem e enquadramento.","experience":"A audiência experimenta clareza inicial, surpresa reconhecível ou alívio por conseguir nomear algo antes difuso.","shift":"A realidade passa a ser vista como existente, relevante e digna de investigação.","early_signals":"Adoção da linguagem, reformulação do problema, perguntas mais precisas, salvamentos e compartilhamentos contextualizados."},"manifestations":[{"nature":"Gesto autoral","options":"observar, distinguir, nomear, revelar, tornar visível, reorganizar uma leitura","note":"O produtor oferece acuidade, não superioridade."},{"nature":"Estrutura narrativa","options":"contraste entre aparência e estrutura; sintomas que revelam um padrão; antes e depois da percepção; mito e realidade; paradoxo; pergunta reveladora","note":"A narrativa deve abrir percepção, não fabricar suspense vazio."},{"nature":"Tipo de pauta","options":"sinais de um fenômeno; padrões invisíveis; conceitos que faltavam; erros de enquadramento; mudanças de contexto; relações pouco percebidas","note":"A pauta deve nomear algo específico o bastante para ser observado."},{"nature":"Experiência proposta","options":"pergunta de observação; mapa simples; lista diagnóstica não clínica; comparação; lente para reler uma situação","note":"Não exigir confissão, adesão ou exposição pessoal."},{"nature":"Interação ou convite","options":"observar a própria realidade; identificar onde o fenômeno aparece; compartilhar com quem precisa da distinção; continuar investigando","note":"O CTA deve ser proporcional ao estágio inicial da jornada."},{"nature":"Expressão visual","options":"cenas de observação; detalhes contextuais; contraste visual; mapas, diagramas ou sequências que tornam relações visíveis","note":"A imagem não deve dramatizar artificialmente o problema."},{"nature":"Adaptação por canal","options":"carrossel de distinções; vídeo curto de enquadramento; artigo analítico; pergunta comentada; fala de abertura; fotografia contextual","note":"O canal altera a densidade, não o movimento."}],"examples":["Chamamos de falta de engajamento aquilo que pode ser perda de sentido.","O conflito visível talvez seja apenas o lugar onde uma tensão sistêmica aparece.","Nem todo cansaço vem do excesso de trabalho; parte dele nasce de sustentar uma forma de liderar que já perdeu vitalidade.","Quando o discurso muda, mas as relações permanecem iguais, a transformação ainda não aconteceu."],"is_not":["alcance ou awareness de marca","chamar atenção por qualquer meio","repetir uma verdade genérica","explicar tudo sobre um tema","diagnosticar pessoas à distância","fazer a audiência admitir que possui um problema","induzir identificação emocional","construir intimidade ou confiança","apresentar uma solução ou convocar para ação"],"boundaries":[{"acj":"ACJ-02","difference":"Reconhecimento torna uma realidade visível; Identificação ajuda a pessoa a localizar-se nela."},{"acj":"ACJ-03","difference":"Reconhecimento cria um objeto comum de atenção; Conexão constrói qualidade de vínculo e presença relacional."},{"acj":"ACJ-04","difference":"Reconhecimento amplia percepção; Experimentação permite viver, testar ou praticar uma possibilidade."},{"acj":"ACJ-05","difference":"Reconhecimento inaugura ou renova uma leitura; Aprofundamento amplia integração, densidade e continuidade."}],"failure_modes":[{"deviation":"Nomeação genérica","class":"conteúdo","alert":"A frase parece verdadeira, mas não permite observar nada novo."},{"deviation":"Choque sem distinção","class":"execução","alert":"Há reação, mas a audiência não consegue explicar o que passou a ver."},{"deviation":"Problema fabricado","class":"conteúdo","alert":"O conteúdo exagera sintomas ou cria um inimigo para produzir urgência."},{"deviation":"Diagnóstico indevido","class":"atribuição","alert":"A ideia tenta localizar a pessoa antes de tornar a realidade suficientemente observável."},{"deviation":"Explicação excessiva","class":"conteúdo","alert":"A densidade fecha a investigação ou antecipa Aprofundamento."},{"deviation":"Repetição saturada","class":"contexto","alert":"A mesma distinção reaparece sem revelar nova camada."},{"deviation":"Métrica confundida com movimento","class":"contexto","alert":"Alcance, curtida ou clique são tratados como prova de reconhecimento."},{"deviation":"Baixa distribuição","class":"distribuição","alert":"A hipótese sobre a arquitetura é rejeitada sem exposição minimamente adequada."}],"saturation_signals":["queda de atenção apesar de boa clareza","respostas que apenas repetem uma linguagem já dominada","percepção de que a campanha “só aponta problemas”","distância crescente entre reconhecer e encontrar um próximo movimento","excesso de variações sobre a mesma tensão sem ampliação de repertório"],"integrity_risks":["usar autoridade para impor uma leitura como verdade final","transformar complexidade sistêmica em rótulos totalizantes","explorar medo, culpa ou inadequação para gerar atenção","apropriar-se de dores da audiência sem oferecer precisão ou responsabilidade","apresentar inferências como fatos comprovados"],"results":[{"level":"Audiência","signal":"A pessoa consegue nomear a realidade, reformular o problema ou indicar o padrão percebido.","indicator":"Comentários com linguagem própria, perguntas mais precisas, salvamentos e compartilhamentos contextualizados.","window":"Imediata e curta.","limitation":"Reação, alcance ou concordância não demonstram por si só reconhecimento."},{"level":"Jornada","signal":"A realidade torna-se relevante o bastante para ser investigada, permitindo Identificação, Conexão, Experimentação ou Aprofundamento posteriores.","indicator":"Continuidade de consumo, retorno ao tema, navegação para conteúdos relacionados e qualidade das respostas seguintes.","window":"Curta a média.","limitation":"Continuidade pode ser influenciada por distribuição, formato, timing e familiaridade prévia."},{"level":"Negócio","signal":"Aumenta a consciência qualificada sobre o campo de atuação da Bee e a relevância de sua lente.","indicator":"Crescimento de audiência qualificada, visitas a ativos de contexto, entrada em fluxos e aumento de demanda informada.","window":"Média.","limitation":"Conversão não é objetivo necessário nem prova isolada desta ACJ."}],"learning_questions":["Que realidades a audiência sente, mas ainda não consegue nomear?","Quais distinções reorganizam a leitura sem exigir explicação excessiva?","A audiência reconhece melhor por sinais concretos, contraste, conceito, pergunta ou enquadramento sistêmico?","Que linguagem é adotada espontaneamente nas respostas?","Em que ponto o Reconhecimento deixa de abrir percepção e passa a repetir algo já sabido?","Quais temas pedem transição imediata para Identificação ou Experimentação?","Que tipos de evidência ampliam credibilidade sem fechar a investigação?"],"confounders":["tema em alta ou acontecimento externo","força emocional do assunto","notoriedade do produtor ou participação de terceiros","título sensacionalista","formato, qualidade visual ou distribuição atípica","familiaridade prévia da audiência com a linguagem","sobreposição com Identificação","CTA ou oferta inseridos cedo demais","tamanho e composição da amostra"],"hypotheses":[{"hypothesis":"Sinais concretos antes do conceito favorecem Reconhecimento em audiências menos familiarizadas.","variable":"Ordem entre sinais e conceito.","control":"Mesmo tema, promessa, canal e janela.","signal":"Maior reformulação espontânea do fenômeno.","decision":"Repetição do padrão em mais de uma ocorrência comparável."},{"hypothesis":"Uma pergunta de observação produz mais Reconhecimento do que uma afirmação conclusiva em temas complexos.","variable":"Abertura interrogativa ou afirmativa.","control":"Mesma distinção e densidade.","signal":"Respostas mais específicas e menos polarizadas.","decision":"Coerência entre respostas qualitativas e continuidade da jornada."},{"hypothesis":"Enquadrar a relação sistêmica desloca melhor a culpa individual do que apenas listar sintomas.","variable":"Relação sistêmica versus lista.","control":"Mesmo fenômeno e público.","signal":"Linguagem menos individualizante e perguntas sobre contexto e relações.","decision":"Padrão sustentado sem perda relevante de clareza."}],"transitions":["Reconhecimento → Identificação: quando a pessoa precisa localizar-se na realidade que passou a perceber","Reconhecimento → Conexão: quando a realidade percebida pede presença, confiança ou qualidade de vínculo","Reconhecimento → Experimentação: quando a melhor forma de compreender a implicação é testar outra possibilidade","Reconhecimento → Aprofundamento: quando já existe repertório e a nova distinção abre uma camada mais densa","Reconhecimento → Reconhecimento: quando outra camada precisa tornar-se visível antes de qualquer mudança de movimento"],"short":"Eu vejo.","purpose":"Tornar visível e nomeável algo que já está acontecendo.","effect":"É isso. Agora consigo ver e nomear.","color":"#D4A017","paths":["Diagnóstico sistêmico","Ver sistêmico / espelhamento da realidade","Provocação de crença","Cases","Educação / conceitos"],"editorials":["diagnostico-sistemico","provocacao-de-crenca","case-anonimizado"]}'::jsonb, 'docs/acj/ACJ-01_Reconhecimento_v0.1.md', now()),
  ('ACJ-02', '0.1', 'in_validation', 'Identificação', 'Eu me vejo.', 'Fazer a realidade percebida encontrar a experiência concreta da pessoa.', 'Isso está acontecendo comigo.', 'Como a pessoa pode localizar-se, com liberdade e precisão, na realidade que passou a perceber?',
   'realidade reconhecida, mas ainda externa, genérica ou sem relevância pessoal explícita', 'relevância pessoal percebida e autolocalização consciente, sem rotulação imposta', 'espelhamento aberto por cenas, perguntas, tensões e possibilidades de autolocalização', '#5E9B3A', ARRAY['historia-pessoal-vulneravel','depoimento-narrativizado','case-anonimizado','diagnostico-sistemico']::text[], '{"id":"ACJ-02","name":"Identificação","version":"0.1","status":"in_validation","document_ref":"docs/acj/ACJ-02_Identificacao_v0.1.md","primary_question":"Como a pessoa pode localizar-se, com liberdade e precisão, na realidade que passou a perceber?","state_from":"realidade reconhecida, mas ainda externa, genérica ou sem relevância pessoal explícita","state_to":"relevância pessoal percebida e autolocalização consciente, sem rotulação imposta","mechanism":"espelhamento aberto por cenas, perguntas, tensões e possibilidades de autolocalização","central_phrase":"uma realidade começa a mover alguém quando deixa de ser apenas verdadeira e passa a dizer respeito à sua própria experiência.","definition":"Identificação é a arquitetura que permite à pessoa localizar-se, com liberdade e precisão, em uma realidade, tensão, possibilidade ou pergunta apresentada pelo conteúdo. Seu movimento ocorre quando algo que já podia ser percebido no campo passa a adquirir relevância pessoal: a audiência reconhece traços de sua experiência, escolhas, contradições, desejos ou contexto naquilo que está sendo elaborado. Ela não define quem a pessoa é, não exige confissão e não produz necessariamente vínculo com Marcos, com a Bee ou com outras pessoas. Seu resultado essencial é: “isso diz respeito a mim ou à realidade que vivo, e consigo perceber de que modo”.","purposes":["diminuir a distância entre uma realidade reconhecida e a experiência concreta da pessoa","favorecer autolocalização sem impor diagnósticos, identidades ou conclusões","dar linguagem a experiências pessoais que ainda não haviam sido articuladas","revelar contradições, escolhas, desejos e possibilidades presentes na própria trajetória","ampliar a pertinência subjetiva da jornada","preparar, quando adequado, movimentos de Conexão, Experimentação ou Aprofundamento"],"indications":["a audiência reconhece um fenômeno, mas o percebe como externo ou genérico","existe distância entre compreensão intelectual e relevância pessoal","pessoas vivem experiências semelhantes, mas ainda não encontram linguagem para se localizar nelas","a campanha precisa mostrar para quem determinada questão é relevante sem recorrer apenas a segmentação demográfica","há contradições, dilemas ou aspirações que podem funcionar como espelhos","a pessoa precisa perceber seu lugar, participação ou implicação antes de experimentar outro caminho","é necessário qualificar afinidade com uma jornada, tema ou proposta","uma nova camada de autopercepção pode reabrir uma jornada já conhecida"],"preconditions":["oferecer referência suficiente para que a pessoa compreenda a realidade em que se localizará","trabalhar com situações, tensões ou possibilidades plausíveis e reconhecíveis","preservar graus, nuances e diferenças de contexto","permitir que a pessoa não se identifique sem sentir-se excluída ou invalidada","distinguir espelhamento de diagnóstico","evitar promessas de que o produtor conhece a pessoa melhor do que ela própria","manter coerência com a experiência real de Marcos e com o repertório da Bee"],"contraindications":["a realidade ainda não está suficientemente visível ou nomeada","a principal necessidade é construir confiança, reciprocidade ou senso de pertencimento","a pessoa já se localiza na questão e precisa experimentar uma alternativa","a jornada pede continuidade, integração ou maior densidade","o conteúdo depende de generalizações vagas para que todos se reconheçam","a ideia exige expor vulnerabilidades que não são necessárias ao movimento","a linguagem tende a fixar identidades, patologizar experiências ou induzir culpa"],"timing":["depois que uma realidade já se tornou minimamente reconhecível, ainda que no mesmo conteúdo","quando há consumo e concordância, mas pouca apropriação pessoal","antes de convites que exigem participação, exposição, escolha ou compromisso","em momentos de transição profissional, organizacional ou identitária","quando a campanha precisa diferenciar afinidade real de interesse superficial","em reentradas, quando um novo contexto permite à pessoa reler a própria trajetória"],"mechanism_steps":{"origin":"A realidade é compreensível, mas permanece externa, genérica ou sem implicação pessoal nítida.","operation":"O conteúdo oferece espelhos precisos e plurais que convidam à autolocalização.","experience":"A pessoa reconhece aspectos de si, de suas relações ou de seu contexto sem sentir-se rotulada.","shift":"A realidade passa de pertinente em geral a pessoalmente relevante.","early_signals":"Linguagem em primeira pessoa, relatos situacionais, perguntas autorreferidas e reconhecimento de tensões ou possibilidades próprias."},"manifestations":[{"nature":"Gesto autoral","options":"espelhar, perguntar, reconhecer nuances, narrar uma experiência, explicitar uma contradição, devolver uma escolha","note":"Marcos oferece linguagem e presença sem dizer à pessoa quem ela é."},{"nature":"Estrutura narrativa","options":"cena reconhecível; dilema; diálogo interno; escolha difícil; contraste entre papel e experiência; aspiração ainda não assumida; história autoral que abre espelho","note":"A narrativa deve permitir múltiplas formas de entrada."},{"nature":"Tipo de pauta","options":"sinais de autolocalização; perguntas que um líder evita; tensões entre resultado e sentido; padrões de escolha; experiências de transição; possibilidades desejadas","note":"A pauta não deve transformar um traço em identidade total."},{"nature":"Experiência proposta","options":"escala de percepção; pergunta reflexiva; escolha entre situações; inventário não diagnóstico; releitura de uma cena; reconhecimento de uma aspiração","note":"A resposta privada deve ser suficiente; exposição pública é opcional."},{"nature":"Interação ou convite","options":"observar onde algo aparece; completar uma frase; escolher a situação mais próxima; nomear uma tensão; continuar a investigação","note":"Evitar CTAs que premiem vulnerabilidade performática."},{"nature":"Expressão visual","options":"retratos autênticos; cenas cotidianas; gestos e contextos reconhecíveis; proximidade sem invasão; sequências que mostram escolhas ou tensões","note":"A imagem deve ampliar a possibilidade de espelho, não impor um personagem ideal."},{"nature":"Adaptação por canal","options":"carrossel de cenas ou perguntas; vídeo autoral; relato no LinkedIn; enquete com gradações; texto reflexivo; fala com pergunta de autolocalização","note":"O canal altera a forma de resposta, não a liberdade de identificação."}],"examples":["Você compreende o que precisa mudar, mas percebe que continua decidindo a partir do mesmo lugar?","Há momentos em que a competência que trouxe você até aqui começa a limitar o próximo passo.","Talvez você não esteja cansado de liderar, mas de sustentar sozinho uma forma de liderança que já não faz sentido.","Alguns líderes não buscam uma nova técnica. Buscam voltar a reconhecer-se nas escolhas que fazem."],"is_not":["segmentar pessoas por cargo, idade ou setor","usar a expressão “se você...”","obter concordância ou reação emocional","classificar personalidades","atribuir dores, traumas ou intenções à audiência","fazer diagnóstico psicológico, clínico ou organizacional","induzir exposição pessoal","criar pertencimento ou intimidade com o produtor","prometer que todos viveram a mesma experiência"],"boundaries":[{"acj":"ACJ-01","difference":"Reconhecimento torna uma realidade visível; Identificação permite à pessoa localizar-se nela."},{"acj":"ACJ-03","difference":"Identificação relaciona a pessoa à realidade apresentada; Conexão qualifica o vínculo com o produtor, a comunidade ou o campo relacional."},{"acj":"ACJ-04","difference":"Identificação produz autolocalização; Experimentação cria contato vivido com uma possibilidade."},{"acj":"ACJ-05","difference":"Identificação torna a questão pessoalmente relevante; Aprofundamento sustenta exploração, integração e continuidade."}],"failure_modes":[{"deviation":"Efeito Barnum","class":"conteúdo","alert":"A descrição é tão ampla que qualquer pessoa poderia aceitá-la."},{"deviation":"Rotulação","class":"conteúdo","alert":"Uma situação passageira é apresentada como identidade fixa."},{"deviation":"Confissão induzida","class":"execução","alert":"O CTA pressiona a pessoa a expor vulnerabilidade para demonstrar pertencimento."},{"deviation":"Dor presumida","class":"atribuição","alert":"O conteúdo declara o que a audiência sente sem oferecer espaço de escolha."},{"deviation":"Espelho idealizado","class":"conteúdo","alert":"A identificação depende de a pessoa desejar parecer com um personagem aspiracional."},{"deviation":"Intimidade simulada","class":"execução","alert":"Linguagem de proximidade é usada para substituir precisão e verdade."},{"deviation":"Reação emocional confundida com autolocalização","class":"contexto","alert":"Emoção, concordância ou polarização são tratadas como prova de Identificação."},{"deviation":"Baixa distribuição","class":"distribuição","alert":"A arquitetura é julgada sem exposição adequada ao público relevante."}],"saturation_signals":["repetição das mesmas dores ou dilemas","sensação de que todo conteúdo fala sobre a audiência sem levá-la adiante","aumento de respostas emocionais sem maior clareza ou movimento","dependência de perguntas pessoais para manter engajamento","perda de nuance por tentativa de fazer todos se identificarem"],"integrity_risks":["explorar vulnerabilidade para aumentar resposta","fixar pessoas em dores, papéis ou identidades convenientes à oferta","utilizar pseudodiagnósticos ou linguagem terapêutica sem base","transformar experiência autoral em verdade universal","confundir proximidade algorítmica com relevância pessoal real","excluir silenciosamente quem não se reconhece no espelho proposto"],"results":[{"level":"Audiência","signal":"A pessoa consegue localizar onde e como a questão aparece em sua experiência, contexto ou aspiração.","indicator":"Linguagem em primeira pessoa, relatos situacionais, respostas a perguntas de gradação, salvamentos e mensagens privadas contextualizadas.","window":"Imediata e curta.","limitation":"Exposição pessoal, emoção ou concordância não comprovam autolocalização."},{"level":"Jornada","signal":"A questão torna-se pessoalmente relevante e aumenta a disponibilidade para continuar, relacionar-se ou experimentar.","indicator":"Retorno ao tema, consumo de sequências, passagem para conteúdos relacionais ou práticos e qualidade das perguntas seguintes.","window":"Curta a média.","limitation":"Continuidade pode decorrer de formato, distribuição, curiosidade ou afinidade prévia."},{"level":"Negócio","signal":"Aumenta a afinidade qualificada entre a experiência da audiência e o campo de atuação da Bee.","indicator":"Inscrições ou contatos com linguagem mais precisa, redução de curiosidade desqualificada e maior pertinência das conversas.","window":"Média.","limitation":"Conversão não é necessária nem suficiente para comprovar Identificação."}],"learning_questions":["A audiência se localiza melhor por situações, tensões, escolhas, valores ou aspirações?","Que grau de especificidade produz precisão sem fechar o espelho?","Quais perguntas favorecem autopercepção sem induzir uma resposta desejada?","Quando a história de Marcos abre espelho e quando concentra atenção apenas nele?","Que linguagem em primeira pessoa emerge espontaneamente?","Que sinais indicam passagem de autolocalização para vínculo, experimentação ou aprofundamento?","Quando a repetição de dores deixa de gerar relevância e passa a fixar a audiência nelas?"],"confounders":["intensidade emocional do tema","incentivo público à confissão","desejo de pertencimento ao grupo","história pessoal de Marcos com alta força narrativa","linguagem popular ou tema em alta","segmentação muito estreita","CTA, oferta ou promessa que contaminam a resposta","formato interativo que eleva participação independentemente do movimento","sobreposição com Reconhecimento ou Conexão"],"hypotheses":[{"hypothesis":"Cenas específicas favorecem autolocalização mais precisa do que descrições de traços.","variable":"Cena concreta versus traço abstrato.","control":"Mesmo tema, canal, densidade e janela.","signal":"Mais respostas situacionais e menos concordância genérica.","decision":"Repetição do padrão em mais de uma ocorrência comparável."},{"hypothesis":"Perguntas com gradação preservam mais liberdade do que alternativas binárias.","variable":"Escala versus sim ou não.","control":"Mesma tensão e mesmo CTA.","signal":"Maior nuance na linguagem e menor polarização.","decision":"Coerência entre qualidade das respostas e continuidade da jornada."},{"hypothesis":"Espelhos baseados em contradições produzem identificação mais profunda do que listas de dores.","variable":"Contradição versus dor.","control":"Mesmo público e contexto.","signal":"Mais articulação de escolhas, tensões e implicações pessoais.","decision":"Padrão sustentado sem aumento de culpa ou rotulação."}],"transitions":["Identificação → Reconhecimento: quando a autolocalização revela que ainda falta compreender o campo mais amplo","Identificação → Conexão: quando a pessoa precisa encontrar presença, confiança, reciprocidade ou pertencimento","Identificação → Experimentação: quando perceber-se na questão abre disponibilidade para testar outra possibilidade","Identificação → Aprofundamento: quando a relevância pessoal sustenta desejo de compreender, integrar ou continuar","Identificação → Identificação: quando outra tensão ou possibilidade precisa ser localizada antes de mudar o movimento"],"short":"Eu me vejo.","purpose":"Fazer a realidade percebida encontrar a experiência concreta da pessoa.","effect":"Isso está acontecendo comigo.","color":"#5E9B3A","paths":["Histórias pessoais","Situações do líder","Cases","Depoimentos","Diagnóstico sistêmico próximo do cotidiano"],"editorials":["historia-pessoal-vulneravel","depoimento-narrativizado","case-anonimizado","diagnostico-sistemico"]}'::jsonb, 'docs/acj/ACJ-02_Identificacao_v0.1.md', now()),
  ('ACJ-03', '0.1', 'in_validation', 'Conexão', 'Eu me aproximo.', 'Criar vínculo com Marcos/Bee a partir de algo verdadeiro e compartilhável.', 'Isso me toca. Quero continuar perto desse pensamento e desse lugar.', 'O que precisa acontecer para que a pessoa deixe de apenas consumir o conteúdo e perceba uma relação confiável em que vale permanecer?',
   'relevância percebida, mas com distância relacional, baixa confiança ou experiência solitária', 'presença relacional percebida, confiança suficiente e disponibilidade segura para permanecer, dialogar ou participar', 'presença relacional coerente, reconhecimento mútuo e reciprocidade proporcional', '#DC4C5A', ARRAY['historia-pessoal-vulneravel','bastidor-da-bee','case-anonimizado','reflexao-filosofica-curta','trecho-livro-contextualizado']::text[], '{"id":"ACJ-03","name":"Conexão","version":"0.1","status":"in_validation","document_ref":"docs/acj/ACJ-03_Conexao_v0.1.md","primary_question":"O que precisa acontecer para que a pessoa deixe de apenas consumir o conteúdo e perceba uma relação confiável em que vale permanecer?","state_from":"relevância percebida, mas com distância relacional, baixa confiança ou experiência solitária","state_to":"presença relacional percebida, confiança suficiente e disponibilidade segura para permanecer, dialogar ou participar","mechanism":"presença relacional coerente, reconhecimento mútuo e reciprocidade proporcional","central_phrase":"conexão acontece quando a pessoa não apenas se vê no que é dito, mas percebe que existe alguém — e possivelmente outros — verdadeiramente presente nessa relação.","definition":"Conexão é a arquitetura que transforma consumo ou relevância pessoal em experiência de relação. Seu movimento ocorre quando a audiência percebe presença, coerência, reconhecimento e possibilidade real de reciprocidade com Marcos, com a Bee, com outras pessoas ou com um campo compartilhado de sentido. Ela não exige intimidade, exposição pessoal, resposta imediata ou pertencimento formal. Seu resultado essencial é: “não estou apenas diante de uma mensagem; percebo uma relação confiável na qual posso permanecer e, se quiser, participar”.","purposes":["construir confiança proporcional à relação efetivamente disponível","reduzir a experiência de isolamento sem fabricar intimidade","demonstrar coerência entre discurso, presença e prática","reconhecer a audiência como sujeito, não apenas como alvo de comunicação","abrir espaço para escuta, resposta, diálogo e convivência","tornar visível a existência de uma comunidade ou campo relacional real","sustentar segurança suficiente para movimentos posteriores de experimentação ou aprofundamento"],"indications":["a audiência consome ou se identifica, mas ainda mantém distância relacional","existe clareza sobre o tema, mas pouca confiança em quem conduz a conversa","a jornada exige segurança antes de participação, experimentação ou compromisso","Marcos precisa tornar mais perceptíveis sua presença, experiência, posição ou forma de relação","a audiência precisa perceber que não vive determinada questão isoladamente","uma comunidade real, encontro, conversa ou espaço de troca precisa tornar-se visível","há excesso de conteýo informativo e insuficiência de presença humana","a campanha precisa sustentar continuidade e não apenas novas entradas"],"preconditions":["apoiar-se em pessoas, experiências, relações ou espaços reais","manter coerência entre a proximidade comunicada e a reciprocidade possível","tornar clara a posição de Marcos sem transformar a conversa em autopromoção","preservar limites entre presença pública, relação profissional e intimidade privada","oferecer alguma forma verdadeira de escuta, resposta, convivência ou continuidade","respeitar consentimento, contexto e privacidade de terceiros","não fabricar depoimentos, clientes, eventos, conversas, comunidade ou resultados"],"contraindications":["a audiência ainda não percebe claramente a realidade em questão","falta autolocalização e o principal movimento precisa ser Identificação","a necessidade central é viver ou testar uma possibilidade concreta","já existe vínculo suficiente e a jornada pede continuidade, integração ou densidade","não existe possibilidade real de sustentar a proximidade sugerida","a ideia depende de exposição emocional, histórias de terceiros ou intimidade fabricada","o principal objetivo é elevar interação, prova social ou simpatia sem necessidade relacional clara"],"timing":["depois que a audiência já percebe relevância, mas ainda não confia suficientemente na relação","antes de convites que exigem participação, presença, vulnerabilidade ou investimento","durante encontros, eventos, comunidades e momentos em que a reciprocidade pode ser vivida","depois de períodos excessivamente conceituais ou promocionais","em momentos de mudança, tensão ou incerteza que pedem presença coerente","no pós-experiência, quando é necessário sustentar relação e continuidade"],"mechanism_steps":{"origin":"A pessoa percebe relevância, mas permanece distante, solitária, desconfiada ou sem experiência de relação.","operation":"Marcos, a Bee ou a comunidade tornam presença, posição, escuta e possibilidade de reciprocidade perceptíveis.","experience":"A pessoa sente-se reconhecida como sujeito e percebe que existe uma relação possível sem coerção ou promessa de intimidade.","shift":"O contato deixa de ser apenas consumo e passa a sustentar confiança, permanência, diálogo ou participação voluntária.","early_signals":"Retorno recorrente, respostas relacionais, perguntas dirigidas, diálogo, referências à presença de Marcos ou da comunidade e interações entre participantes."},"manifestations":[{"nature":"Gesto autoral","options":"testemunhar, responder, escutar, reconhecer, acolher, posicionar-se, compartilhar uma experiência situada, devolver uma pergunta","note":"Presença não exige exposição irrestrita."},{"nature":"Estrutura narrativa","options":"história autoral com implicação; resposta a uma pergunta real; conversa; bastidor verdadeiro; encontro; tensão vivida; aprendizado relacional; vozes da comunidade","note":"A história precisa servir à relação, não apenas à imagem do produtor."},{"nature":"Tipo de pauta","options":"o que Marcos está aprendendo; perguntas recebidas; escolhas e limites; cenas de trabalho real; encontros; depoimentos verdadeiros; dilemas compartilhados; princípios em prática","note":"Terceiros exigem consentimento e fidelidade ao contexto."},{"nature":"Experiência proposta","options":"conversa aberta; resposta comentada; encontro ao vivo; escuta; troca entre participantes; espaço seguro de pergunta; reconhecimento de contribuições","note":"A experiência deve corresponder à capacidade real de presença."},{"nature":"Interação ou convite","options":"responder uma pergunta; compartilhar uma perspectiva; participar de conversa; acompanhar uma continuidade; encontrar outras pessoas; entrar em espaço de troca","note":"Evitar pedidos genéricos de engajamento."},{"nature":"Expressão visual","options":"retratos autênticos; conversa real; grupo em interação; workshop; palestra; bastidor; escuta; trabalho com flip chart; contexto de comunidade","note":"A cena deve ter verdade fotográfica e não simular clientes, eventos ou relações inexistentes."},{"nature":"Adaptação por canal","options":"vídeo direto; resposta em comentário; live; artigo autoral; bastidor contextualizado; recorte de encontro real; sequência de comunidade; mensagem de continuidade","note":"Escala do canal não deve prometer reciprocidade individual impossível."}],"examples":["Essa pergunta apareceu em diferentes conversas com líderes nas últimas semanas. Quero respondê-la sem simplificar o que está em jogo.","Eu também precisei reconhecer o limite de uma forma de liderar que durante muito tempo funcionou para mim.","Uma das coisas mais potentes de uma Clareira é perceber que experiências diferentes podem revelar uma mesma tensão sem produzir uma resposta única.","Não tenho uma fórmula para isso. Tenho uma pergunta que venho sustentando na prática e quero compartilhá-la com você."],"is_not":["curtida, comentário ou engajamento","simpatia, carisma ou popularidade","exposição da vida privada","intimidade presumida","contar uma história pessoal por si só","usar tom informal ou chamar a audiência pelo primeiro nome","prova social","pertencimento forçado","disponibilidade ilimitada de Marcos","dependência emocional ou centralidade do produtor"],"boundaries":[{"acj":"ACJ-01","difference":"Reconhecimento cria um objeto comum de atenção; Conexão cria qualidade de relação em torno dele."},{"acj":"ACJ-02","difference":"Identificação relaciona a pessoa à realidade apresentada; Conexão estabelece relação com quem conduz, participa ou sustenta o campo."},{"acj":"ACJ-04","difference":"Conexão produz confiança e disponibilidade relacional; Experimentação cria contato vivido com uma possibilidade."},{"acj":"ACJ-05","difference":"Conexão torna possível permanecer na relação; Aprofundamento sustenta continuidade, integração e densidade."}],"failure_modes":[{"deviation":"Intimidade performática","class":"execução","alert":"Linguagem emocional sugere proximidade que a relação real não sustenta."},{"deviation":"Vulnerabilidade instrumental","class":"conteúdo","alert":"Exposição pessoal é usada para gerar resposta, simpatia ou venda."},{"deviation":"Comunidade cenográfica","class":"conteúdo","alert":"Imagens, falas ou cenas simulam encontros e pertencimento inexistentes."},{"deviation":"Reciprocidade impossível","class":"atribuição","alert":"O conteúdo promete escuta ou acesso que não podem ser oferecidos."},{"deviation":"Engajamento como prova","class":"contexto","alert":"Volume de interação é tratado como evidência de confiança."},{"deviation":"Excesso de centralidade","class":"conteúdo","alert":"Marcos torna-se o objeto principal e a audiência permanece espectadora."},{"deviation":"Terceiros sem consentimento","class":"execução","alert":"Histórias, imagens ou depoimentos são usados sem contexto ou autorização."},{"deviation":"Distribuição sem continuidade","class":"distribuição","alert":"O conteúdo relacional alcança pessoas sem que exista sequência ou espaço de resposta."}],"saturation_signals":["histórias pessoais repetidas sem nova implicação","excesso de bastidores ou imagens de comunidade sem substância relacional","crescimento de familiaridade sem maior confiança ou participação","dependência de exposição pessoal para sustentar atenção","sensação de proximidade que não encontra continuidade real"],"integrity_risks":["explorar solidão, vulnerabilidade ou desejo de pertencimento","criar relação parasocial deliberadamente","transformar comunidade em prova social","usar depoimentos fora de contexto","prometer acesso individual incompatível com a escala","apagar limites profissionais em nome de autenticidade","centralizar o campo em Marcos em vez de favorecer autonomia e relações plurais"],"results":[{"level":"Audiência","signal":"A pessoa percebe presença, coerência e relação possível, demonstrando confiança suficiente para permanecer ou dialogar.","indicator":"Retorno recorrente, respostas dirigidas, perguntas genuínas, mensagens relacionais e referências à postura ou presença de Marcos e da Bee.","window":"Curta a média.","limitation":"Interação, simpatia e exposição pessoal não comprovam confiança."},{"level":"Jornada","signal":"A relação sustenta continuidade, participação e passagem segura para outros movimentos.","indicator":"Retorno a encontros ou conteúdos, participação em espaços de troca, interação entre pessoas e qualidade da permanência.","window":"Média.","limitation":"Permanência pode ser influenciada por frequência, conveniência, formato e incentivo externo."},{"level":"Negócio","signal":"Aumenta a confiança qualificada na Bee e a disposição para entrar em experiências relacionais coerentes.","indicator":"Conversas qualificadas, indicações, participação recorrente, retorno e menor dependência de persuasão transacional.","window":"Média a longa.","limitation":"Compra, retenção ou indicação não provam isoladamente que a Conexão ocorreu."}],"learning_questions":["Que formas de presença tornam Marcos mais perceptível sem concentrar a jornada nele?","Que elementos geram confiança: coerência, posição, resposta, história, bastidor, continuidade ou comunidade?","Quando uma história autoral abre relação e quando se torna autopromoção?","Que grau de reciprocidade a audiência espera e qual pode ser realmente sustentado?","Que sinais distinguem pertencimento real de familiaridade ou efeito parasocial?","Como a comunidade pode aparecer sem ser reduzida a prova social?","Em que ponto Conexão precisa dar lugar a Experimentação ou Aprofundamento?"],"confounders":["notoriedade, carisma ou aparência de Marcos","intensidade emocional da história","presença de pessoas conhecidas ou clientes relevantes","evento recente com alta energia coletiva","incentivo a comentar ou participar","formato ao vivo","tamanho e proximidade prévia da comunidade","oferta, exclusividade ou escassez","sobreposição com Identificação","resposta operacional rápida confundida com qualidade relacional"],"hypotheses":[{"hypothesis":"Responder a perguntas reais produz mais Conexão do que solicitar interação genérica.","variable":"Pergunta real versus CTA de engajamento.","control":"Mesmo tema, canal e janela.","signal":"Mais perguntas subsequentes, retorno e linguagem relacional.","decision":"Padrão repetido em ocorrências comparáveis sem depender de volume bruto."},{"hypothesis":"Histórias autorais geram mais confiança quando explicitam implicação e limite, não apenas vulnerabilidade.","variable":"História com ou sem implicação e limite.","control":"Mesmo tema e densidade.","signal":"Respostas sobre coerência e aprendizado, não apenas simpatia.","decision":"Coerência entre sinais qualitativos e continuidade da relação."},{"hypothesis":"Contextos reais de trabalho favorecem Conexão mais sustentável do que cenas de autoridade encenada.","variable":"Cena real versus cena produzida para status.","control":"Mesmo produtor, mensagem e canal.","signal":"Mais perguntas contextualizadas e menor concentração em imagem ou prestígio.","decision":"Padrão sustentado sem perda relevante de clareza ou alcance qualificado."}],"transitions":["Conexão → Reconhecimento: quando a relação abre acesso a uma realidade ainda não percebida","Conexão → Identificação: quando a confiança permite à pessoa localizar-se com maior honestidade","Conexão → Experimentação: quando a relação oferece segurança suficiente para viver outra possibilidade","Conexão → Aprofundamento: quando confiança e permanência sustentam maior compromisso e densidade","Conexão → Conexão: quando o vínculo precisa ser sustentado ou ampliado entre diferentes atores do campo"],"short":"Eu me aproximo.","purpose":"Criar vínculo com Marcos/Bee a partir de algo verdadeiro e compartilhável.","effect":"Isso me toca. Quero continuar perto desse pensamento e desse lugar.","color":"#DC4C5A","paths":["Histórias pessoais","Bastidores Bee","Cases vividos","Escolhas e dilemas reais","Reflexões pessoais","Trechos de livro contextualizados"],"editorials":["historia-pessoal-vulneravel","bastidor-da-bee","case-anonimizado","reflexao-filosofica-curta","trecho-livro-contextualizado"]}'::jsonb, 'docs/acj/ACJ-03_Conexao_v0.1.md', now()),
  ('ACJ-04', '0.1', 'in_validation', 'Experimentação', 'Eu vejo diferente.', 'Permitir que a pessoa experimente, ainda que brevemente, outra maneira de perceber.', 'Nunca tinha olhado dessa forma.', 'Que experiência possível, segura e delimitada permitirá à pessoa entrar em contato com outra forma de perceber, escolher, relacionar-se ou agir?',
   'compreensão, relevância ou confiança ainda sem evidência vivida de outra possibilidade', 'contato direto com uma possibilidade, produzindo evidência própria, aprendizagem e maior agência', 'convite de baixo risco, experiência delimitada e observação reflexiva do que ela produz', '#2F7FC1', ARRAY['diagnostico-sistemico','case-anonimizado','provocacao-de-crenca','reflexao-filosofica-curta']::text[], '{"id":"ACJ-04","name":"Experimentação","version":"0.1","status":"in_validation","document_ref":"docs/acj/ACJ-04_Experimentacao_v0.1.md","primary_question":"Que experiência possível, segura e delimitada permitirá à pessoa entrar em contato com outra forma de perceber, escolher, relacionar-se ou agir?","state_from":"compreensão, relevância ou confiança ainda sem evidência vivida de outra possibilidade","state_to":"contato direto com uma possibilidade, produzindo evidência própria, aprendizagem e maior agência","mechanism":"convite de baixo risco, experiência delimitada e observação reflexiva do que ela produz","central_phrase":"uma possibilidade se torna real quando a pessoa pode experimentá-la em escala segura e observar, por si mesma, o que muda.","definition":"Experimentação é a arquitetura que transforma compreensão, identificação ou confiança em contato vivido com outra possibilidade. Seu movimento ocorre quando o conteúdo convida a pessoa a perceber, escolher, relacionar-se ou agir de modo diferente em uma experiência segura, delimitada e observável. Ela não exige resultado positivo, mudança definitiva ou compromisso prolongado. Seu resultado essencial é: “eu pude testar algo diferente, observar o que aconteceu e produzir evidência própria sobre essa possibilidade”.","purposes":["converter compreensão em contato direto com uma possibilidade","permitir que a pessoa produza evidência própria, ainda que inicial","ampliar agência por meio de escolhas e observações concretas","tornar conceitos perceptíveis no corpo, nas relações, nas decisões ou na prática","reduzir o risco de adesão baseada apenas em crença, autoridade ou promessa","revelar condições, limites e perguntas que só aparecem na experiência","qualificar a disponibilidade para continuidade ou aprofundamento"],"indications":["a audiência compreende a ideia, mas ainda não possui evidência vivida","existe interesse ou identificação, mas pouca passagem para a prática","a jornada está excessivamente conceitual","uma possibilidade pode ser testada em escala pequena e segura","a pessoa precisa comparar diretamente duas formas de perceber, escolher ou agir","uma prática simples pode revelar limites, condições ou novas perguntas","é necessário oferecer uma amostra verdadeira da abordagem sem simular o percurso completo","a campanha precisa qualificar prontidão antes de um compromisso maior"],"preconditions":["ter relação clara com o movimento e com a ideia apresentada","possuir escopo, duração, risco e expectativa proporcionais","permitir escolha e interrupção sem punição simbólica","oferecer instrução suficiente para a pessoa agir com segurança","esclarecer o que observar, sem prescrever o resultado correto","reconhecer quando a prática exige facilitação, contexto profissional ou acompanhamento","incluir algum espaço de reflexão, integração ou devolutiva","não prometer que uma microexperiência equivale a uma transformação completa"],"contraindications":["a pessoa ainda não compreende minimamente o que está sendo proposto","falta segurança relacional para uma experiência que envolve exposição, grupo ou vulnerabilidade","a prática pode gerar risco emocional, profissional, financeiro, jurídico ou físico desproporcional","o movimento exige contexto, formação ou facilitação que o conteúdo não oferece","a audiência já experimentou e precisa sustentar, integrar ou aprofundar","o chamado à ação serve apenas para aumentar interação ou conversão","o exercício é decorativo e não produz observação relevante","existe uma única resposta aceita, disfarçada de experiência aberta"],"timing":["depois que a audiência possui compreensão e segurança suficientes para testar algo","antes de convites que exigem compromisso, investimento ou continuidade","durante masterclasses, encontros, workshops, Clareiras e contextos com facilitação","em sequências nas quais conceitos precisam ganhar concretude","quando a audiência demonstra fadiga de conteúdo e demanda experiência","depois de uma prática, para observar, integrar e decidir o próximo movimento"],"mechanism_steps":{"origin":"A pessoa compreende, se identifica ou confia, mas ainda não viveu outra possibilidade de modo observável.","operation":"O conteúdo oferece contexto, escolha, instrução e limite para uma experiência proporcional.","experience":"A pessoa testa uma nova percepção, decisão, relação ou ação e observa o que emerge.","shift":"A possibilidade deixa de ser apenas conceitual e passa a possuir evidência vivida, ainda que parcial ou inconclusiva.","early_signals":"Realização da prática, relatos de observação, comparações, novas perguntas, ajustes e desejo de repetir ou continuar."},"manifestations":[{"nature":"Gesto autoral","options":"convidar, demonstrar, facilitar, propor um teste, orientar atenção, devolver observação, legitimar resultados diferentes","note":"Marcos oferece condições para a experiência, não o resultado esperado."},{"nature":"Estrutura narrativa","options":"situação e escolha; antes, durante e depois da prática; demonstração; microcaso; comparação entre abordagens; experimento comentado","note":"A narrativa deve deixar claro o que foi testado e o que não pode ser concluído."},{"nature":"Tipo de pauta","options":"perguntas de observação; micropráticas; ensaios de decisão; conversa experimental; mudança de perspectiva; aplicação de um princípio; simulação; demonstração ao vivo","note":"A prática deve realizar o conceito, não apenas ilustrá-lo."},{"nature":"Experiência proposta","options":"pausa de observação; escrita breve; escuta; escolha alternativa; conversa com nova pergunta; leitura de campo; teste em reunião; exercício guiado; prática em grupo","note":"Escala e risco precisam ser compatíveis com o canal."},{"nature":"Interação ou convite","options":"experimentar por um período; comparar duas abordagens; registrar o que ocorreu; trazer uma observação; participar de encontro prático; repetir com ajuste","note":"Compartilhar o resultado é opcional, salvo quando o contexto de grupo foi previamente acordado."},{"nature":"Expressão visual","options":"Marcos facilitando; workshop; palestra com atividade; flip chart; grupo em prática; mãos, materiais e anotações; demonstração real; processo em andamento","note":"A imagem deve registrar ação real ou simular apenas quando claramente apresentada como ilustração."},{"nature":"Adaptação por canal","options":"exercício em carrossel; áudio guiado; vídeo demonstrativo; enquete reflexiva; worksheet; live prática; desafio breve; encontro; experiência presencial","note":"Interatividade técnica não é sinônimo de Experimentação."}],"examples":["Na próxima conversa, experimente suspender a resposta por alguns segundos e perguntar o que ainda não está sendo dito. Depois observe o que muda no campo.","Escolha uma decisão atual. Antes de buscar a solução, liste quem e o que será afetado por ela. Veja se a pergunta inicial permanece a mesma.","Durante um dia, perceba quantas vezes você entra numa reunião já sabendo o que precisa acontecer. Não tente corrigir. Apenas registre o efeito dessa posição.","Compare duas conversas: em uma, ofereça orientação; na outra, ajude a pessoa a formular melhor a própria pergunta. Observe o que cada movimento produz."],"is_not":["qualquer CTA ou interação","clicar, comentar, compartilhar ou comprar","consumir conteúdo interativo","cumprir uma tarefa sem observar o que ela produz","aplicar uma fórmula para obter o resultado correto","desafio gamificado por si só","demonstração feita apenas pelo produtor","promessa de transformação rápida","substituir formação, acompanhamento ou responsabilidade profissional","obrigar a pessoa a expor publicamente o resultado"],"boundaries":[{"acj":"ACJ-01","difference":"Reconhecimento torna uma realidade visível; Experimentação permite contato vivido com outra possibilidade."},{"acj":"ACJ-02","difference":"Identificação produz autolocalização; Experimentação coloca uma percepção, escolha ou ação em teste."},{"acj":"ACJ-03","difference":"Conexão oferece segurança e relação; Experimentação usa condições suficientes para viver uma possibilidade."},{"acj":"ACJ-05","difference":"Experimentação produz contato e evidência inicial; Aprofundamento sustenta continuidade, integração e complexidade."}],"failure_modes":[{"deviation":"Exercício decorativo","class":"conteúdo","alert":"A tarefa entretém ou ilustra, mas não permite observar o movimento proposto."},{"deviation":"Resultado prescrito","class":"conteúdo","alert":"A experiência só é considerada válida quando confirma a tese do produtor."},{"deviation":"Complexidade desproporcional","class":"atribuição","alert":"A prática exige repertório, segurança ou facilitação que o contexto não oferece."},{"deviation":"Exposição forçada","class":"execução","alert":"Participar depende de revelar publicamente experiência, vulnerabilidade ou resultado."},{"deviation":"Ação sem integração","class":"execução","alert":"Não existe orientação sobre o que observar ou como refletir depois."},{"deviation":"Conversão disfarçada","class":"atribuição","alert":"Comprar, inscrever-se ou solicitar contato é apresentado como experimento."},{"deviation":"Sucesso anedótico","class":"contexto","alert":"Um relato positivo é usado para validar universalmente a prática."},{"deviation":"Barreira de acesso","class":"distribuição","alert":"A experiência depende de recurso, tempo ou ambiente incompatível com o público ou canal."}],"saturation_signals":["acúmulo de exercícios sem integração","baixa conclusão acompanhada de excesso de convites práticos","participação mecânica sem novas observações","repetição do mesmo tipo de prática","sensação de que todo conteúdo exige uma tarefa","desejo de “fazer mais” substituindo a necessidade de compreender ou integrar"],"integrity_risks":["induzir decisões importantes a partir de microexperiências","propor práticas terapêuticas, clínicas ou organizacionais sem contexto adequado","responsabilizar a pessoa quando a experiência não produz o resultado esperado","coletar dados ou relatos sem consentimento claro","confundir desconforto com transformação","usar gamificação, escassez ou pressão social para obter participação","transformar experimentação em demonstração de obediência ao produtor"],"results":[{"level":"Audiência","signal":"A pessoa realiza ou adapta uma experiência, observa efeitos e formula evidência ou pergunta própria.","indicator":"Relatos de observação, comparações, conclusão da prática, novas perguntas, repetição voluntária e ajustes.","window":"Imediata a curta.","limitation":"Participação e conclusão não demonstram aprendizagem nem mudança."},{"level":"Jornada","signal":"A experiência aumenta agência, qualifica prontidão e informa o próximo movimento.","indicator":"Retorno para integrar, busca de aprofundamento, participação em nova experiência e mudança na qualidade das perguntas.","window":"Curta a média.","limitation":"Continuidade pode decorrer de novidade, incentivo, grupo ou satisfação com o formato."},{"level":"Negócio","signal":"A audiência conhece a abordagem da Bee por experiência e pode avaliar com maior qualidade sua pertinência.","indicator":"Participação qualificada em masterclasses, encontros ou jornadas; demanda mais informada; menor dependência de persuasão abstrata.","window":"Média.","limitation":"Inscrição, compra ou presença não comprovam que a experiência produziu o movimento."}],"learning_questions":["Qual é a menor experiência capaz de tornar o movimento perceptível?","Que nível de instrução oferece segurança sem retirar autonomia?","Que práticas funcionam de forma autoguiada e quais exigem facilitação?","O que favorece aprendizagem: demonstração, escolha, repetição, comparação, reflexão ou devolutiva?","Que tipos de experiência ampliam agência e quais geram dependência?","Em que ponto a experimentação precisa dar lugar à integração e ao aprofundamento?","Como distinguir baixa adesão por desenho inadequado, risco percebido, contexto ou distribuição?"],"confounders":["novidade ou efeito lúdico","desejo de agradar o facilitador","pressão do grupo","seleção de participantes mais engajados","habilidade prévia ou familiaridade com a prática","qualidade da facilitação","tempo, ambiente e recursos disponíveis","incentivo, certificado, recompensa ou oferta","relato imediato antes de qualquer integração","sobreposição com Conexão ou Aprofundamento"],"hypotheses":[{"hypothesis":"Uma microprática acompanhada de pergunta de observação produz mais aprendizagem do que a mesma instrução sem integração.","variable":"Presença da pergunta reflexiva.","control":"Mesma prática, canal e janela.","signal":"Relatos mais específicos sobre efeitos, limites e novas perguntas.","decision":"Repetição do padrão em ocorrências comparáveis."},{"hypothesis":"Oferecer duas formas de experimentar aumenta autonomia em relação a uma prescrição única.","variable":"Escolha entre variações.","control":"Mesmo movimento e dificuldade.","signal":"Mais adaptações conscientes e menor linguagem de acerto ou erro.","decision":"Coerência entre conclusão, qualidade das observações e ausência de confusão."},{"hypothesis":"Experiências relacionais complexas geram evidência mais confiável quando facilitadas ao vivo.","variable":"Autoguiada versus facilitada.","control":"Mesmo princípio e público comparável.","signal":"Maior clareza de contexto, segurança e capacidade de integrar resultados diferentes.","decision":"Padrão sustentado sem aumento desproporcional de dependência do facilitador."}],"transitions":["Experimentação → Reconhecimento: quando a prática revela uma realidade antes não percebida","Experimentação → Identificação: quando a experiência ajuda a pessoa a localizar-se de outro modo","Experimentação → Conexão: quando a experiência compartilhada produz relação, confiança ou comunidade","Experimentação → Aprofundamento: quando a evidência inicial abre desejo ou necessidade de continuidade, integração e maior complexidade","Experimentação → Experimentação: quando é necessário repetir, variar ou comparar antes de mudar o movimento"],"short":"Eu vejo diferente.","purpose":"Permitir que a pessoa experimente, ainda que brevemente, outra maneira de perceber.","effect":"Nunca tinha olhado dessa forma.","color":"#2F7FC1","paths":["6 Dimensões aplicadas","Educação sistêmica","Releitura de situações / cases","Perguntas que mudam a observação","Contraste mecanicista × sistêmico"],"editorials":["diagnostico-sistemico","case-anonimizado","provocacao-de-crenca","reflexao-filosofica-curta"]}'::jsonb, 'docs/acj/ACJ-04_Experimentacao_v0.1.md', now()),
  ('ACJ-05', '0.1', 'in_validation', 'Aprofundamento', 'Eu quero ir além.', 'Transformar interesse em desejo de compreender e viver mais profundamente aquela abordagem.', 'Quero ir além. Quero compreender e viver isso.', 'O que precisa ser sustentado, revisitado e integrado para que uma compreensão ou experiência se transforme em capacidade?',
   'compreensão, confiança ou evidência inicial ainda fragmentada, instável ou pouco integrada', 'compreensão e prática integradas ao repertório, com maior capacidade para agir diante da complexidade e com autonomia', 'continuidade estruturada, complexidade progressiva e integração entre compreensão, prática, reflexão e aplicação', '#8562B8', ARRAY['diagnostico-sistemico','case-anonimizado','bastidor-da-bee','trecho-livro-contextualizado']::text[], '{"id":"ACJ-05","name":"Aprofundamento","version":"0.1","status":"in_validation","document_ref":"docs/acj/ACJ-05_Aprofundamento_v0.1.md","primary_question":"O que precisa ser sustentado, revisitado e integrado para que uma compreensão ou experiência se transforme em capacidade?","state_from":"compreensão, confiança ou evidência inicial ainda fragmentada, instável ou pouco integrada","state_to":"compreensão e prática integradas ao repertório, com maior capacidade para agir diante da complexidade e com autonomia","mechanism":"continuidade estruturada, complexidade progressiva e integração entre compreensão, prática, reflexão e aplicação","central_phrase":"aprofundar não é consumir mais; é permanecer o suficiente para integrar, amadurecer e transformar experiência em capacidade.","definition":"Aprofundamento é a arquitetura que sustenta uma compreensão, relação ou experiência ao longo do tempo para que ela deixe de ser apenas inicial, episódica ou dependente de contexto e passe a integrar o repertório da pessoa. Seu movimento ocorre pela combinação de continuidade estruturada, complexidade progressiva, prática, reflexão, aplicação e síntese. A pessoa revisita o que viveu, percebe novas camadas, testa em situações diferentes, confronta limites e produz distinções próprias. Aprofundamento não é uma etapa obrigatoriamente final nem uma quantidade maior de conteúdo. Ele pode acontecer em diferentes momentos da jornada, retornar sobre um mesmo tema e revelar novas necessidades de Reconhecimento, Identificação, Conexão ou Experimentação. Seu resultado essencial é: “isso deixou de ser apenas algo que compreendi ou experimentei; passou a orientar como percebo, escolho e ajo, inclusive em situações novas”.","purposes":["transformar compreensão inicial em repertório utilizável","integrar teoria, experiência, reflexão e aplicação","ampliar a capacidade de lidar com contexto, ambiguidade e complexidade","favorecer transferência da aprendizagem para situações diferentes","sustentar revisitação, prática, feedback e síntese ao longo do tempo","permitir que a pessoa produza linguagem, perguntas e distinções próprias","aumentar autonomia sem romper a possibilidade de comunidade e continuidade","qualificar a prontidão para desafios, responsabilidades ou jornadas mais complexas"],"indications":["já existe compreensão, confiança ou evidência inicial que precisa ser integrada","a audiência demonstra interesse recorrente, mas ainda aplica de forma instável ou literal","um tema exige camadas, contexto e tempo para não ser simplificado","a prática precisa ser retomada em situações variadas","surgem perguntas mais precisas, dilemas ou limites depois da Experimentação","a pessoa necessita articular princípios em vez de apenas reproduzir técnicas","a jornada precisa favorecer autonomia, transferência e autoria","existe prontidão para maior compromisso de atenção, prática ou reflexão","uma comunidade, formação, sequência ou encontro pode sustentar continuidade real"],"preconditions":["partir de uma experiência ou questão relevante para a pessoa","explicitar por que a continuidade é necessária e que capacidade se pretende desenvolver","organizar a complexidade em camadas compreensíveis, sem empobrecer o tema","alternar compreensão, prática, reflexão, aplicação e síntese","oferecer tempo e espaçamento compatíveis com a integração","permitir retomadas sem transformar atraso em fracasso","distinguir apoio, facilitação e comunidade de dependência permanente","reconhecer conhecimentos prévios e caminhos diferentes de aprendizagem","oferecer feedback proporcional quando a prática exigir calibração","tornar visível o que pode ser autoguiado e o que exige contexto ou acompanhamento"],"contraindications":["ainda falta reconhecimento básico da realidade em questão","a pessoa não consegue se localizar minimamente no tema","não existe confiança ou segurança suficiente para continuidade","a audiência ainda precisa de contato inicial e evidência vivida","a proposta apenas aumenta volume, duração ou complexidade aparente","o conteúdo repete as mesmas ideias sem produzir integração","a profundidade é usada para justificar jargão, exclusividade ou superioridade","o percurso exige um compromisso incompatível com o momento ou o contexto da audiência","o verdadeiro objetivo é retenção, dependência ou venda recorrente"],"timing":["depois de uma compreensão, conexão ou experimentação que abriu novas perguntas","quando o intervalo entre contato e aplicação começa a revelar limites reais","em ciclos que permitem revisitação, prática e feedback","durante formações, Clareiras, comunidades, séries, workshops e Jornadas Avançadas","quando a pessoa precisa transferir princípios para outros contextos","quando a jornada demonstra muita inspiração e pouca incorporação","antes ou durante desafios que exigem maior responsabilidade e autonomia"],"mechanism_steps":{"origin":"A pessoa possui insight, confiança ou evidência inicial, mas o aprendizado ainda é fragmentado, instável ou dependente do contexto original.","operation":"A jornada organiza continuidade, revisitação, complexidade progressiva, prática, feedback e síntese.","experience":"A pessoa relaciona camadas, confronta limites, aplica em situações variadas e formula distinções próprias.","shift":"A compreensão ou experiência passa a integrar o repertório e aumenta a capacidade de agir com discernimento e autonomia.","early_signals":"Aplicação em novos contextos, perguntas mais precisas, sínteses próprias, adaptação de princípios, maior qualidade de decisão e menor dependência de instruções."},"manifestations":[{"nature":"Gesto autoral","options":"sustentar uma pergunta, acrescentar camadas, relacionar perspectivas, revisitar, acompanhar, oferecer feedback, sintetizar, devolver autonomia","note":"Marcos não entrega apenas respostas; organiza condições para maturação e autoria."},{"nature":"Estrutura narrativa","options":"série progressiva; princípio, caso e aplicação; revisitação comentada; trajetória de aprendizagem; dilema em camadas; antes, durante e depois; síntese provisória","note":"A progressão precisa produzir nova capacidade, não apenas expectativa pelo próximo conteúdo."},{"nature":"Tipo de pauta","options":"fundamentos; estudos de caso; tensões entre princípios; limites de aplicação; padrões recorrentes; práticas sequenciadas; perguntas avançadas; sínteses transversais","note":"Dificuldade e jargão não são indicadores de profundidade."},{"nature":"Experiência proposta","options":"ciclo de prática e reflexão; aplicação em contextos distintos; diário de aprendizagem; supervisão; estudo em grupo; projeto; workshop; formação; laboratório; Clareira; jornada avançada","note":"Produto, acesso ou duração não definem por si mesmos a arquitetura."},{"nature":"Interação ou convite","options":"retomar uma prática; comparar aplicações; formular uma síntese; trazer um caso; receber e usar feedback; ensinar um princípio com palavras próprias; continuar uma sequência","note":"O convite deve ampliar capacidade e não apenas prolongar permanência."},{"nature":"Expressão visual","options":"Marcos em palestra; apresentação em pé; workshop com flip chart; facilitação de grupo; estudo de caso; comunidade em trabalho; processo acompanhado; anotações e mapas reais","note":"A imagem deve comunicar presença, processo, investigação e prática, sem encenar autoridade artificial."},{"nature":"Adaptação por canal","options":"série de posts; artigo; newsletter; podcast; áudio de aula; vídeo; estudo guiado; live; oficina; comunidade; formação; material de apoio","note":"O desdobramento preserva continuidade e relação entre as partes, em vez de fragmentar o percurso."}],"examples":["Retome a decisão que você observou na semana passada. O que muda quando você inclui agora os efeitos sobre as relações e não apenas sobre o resultado?","Este é o terceiro caso em que o mesmo princípio produz respostas diferentes. O que permanece e o que depende do contexto?","Depois de aplicar a prática em duas situações, formule com suas palavras quando ela ajuda, quando não ajuda e o que você ainda precisa investigar.","Traga uma situação real para a Clareira. Não para receber uma resposta pronta, mas para ampliar a leitura e construir uma intervenção mais consciente."],"is_not":["conteúdo longo por definição","linguagem técnica, abstrata ou difícil","maior volume de informação","repetição do mesmo conteúdo em novos formatos","curso, formação, comunidade ou produto pago por si só","acesso exclusivo ou credencial","etapa avançada de um funil","acúmulo de aulas sem prática e síntese","dependência contínua do produtor ou facilitador","promessa de domínio definitivo sobre um tema complexo"],"boundaries":[{"acj":"ACJ-01","difference":"Reconhecimento torna uma realidade visível; Aprofundamento sustenta sua investigação e integração ao longo do tempo."},{"acj":"ACJ-02","difference":"Identificação produz autolocalização; Aprofundamento permite compreender padrões, variações e possibilidades para além do primeiro espelho."},{"acj":"ACJ-03","difference":"Conexão cria confiança, segurança e relação; Aprofundamento utiliza essa base para sustentar complexidade, prática e autoria."},{"acj":"ACJ-04","difference":"Experimentação produz contato vivido e evidência inicial; Aprofundamento revisita, aplica, integra e transforma a experiência em capacidade."}],"failure_modes":[{"deviation":"Teatro de complexidade","class":"conteúdo","alert":"Jargão, abstração ou dificuldade simulam profundidade sem ampliar compreensão ou capacidade."},{"deviation":"Sobrecarga informacional","class":"conteúdo","alert":"A pessoa recebe mais conceitos, referências e aulas do que consegue relacionar, praticar e integrar."},{"deviation":"Profundidade prematura","class":"atribuição","alert":"A jornada exige elaboração ou compromisso antes de existir base relacional e experiencial suficiente."},{"deviation":"Continuidade sem integração","class":"execução","alert":"A sequência avança, mas não oferece retomada, aplicação, feedback ou síntese."},{"deviation":"Dependência do mentor","class":"execução","alert":"A pessoa precisa continuamente da interpretação ou validação do produtor para decidir ou agir."},{"deviation":"Credencialismo ou fechamento","class":"conteúdo","alert":"Certificação, linguagem interna ou exclusividade substituem evidências de capacidade e autonomia."},{"deviation":"Pagamento como prova","class":"atribuição","alert":"Investimento ou permanência são tratados como demonstração de maturidade, compromisso ou profundidade."},{"deviation":"Barreira de acesso","class":"distribuição","alert":"Ritmo, formato, plataforma ou recursos impedem continuidade mesmo quando existe prontidão."},{"deviation":"Contexto inadequado","class":"contexto","alert":"Um percurso válido para um grupo é generalizado sem considerar repertório, tempo, risco ou necessidade."}],"saturation_signals":["excesso de aulas, leituras ou encontros sem tempo de integração","sensação de atraso permanente","consumo contínuo acompanhado de pouca aplicação","novidade apresentada como profundidade","repetição de conceitos sem novas distinções","dificuldade crescente para sintetizar o que está sendo aprendido","dependência do próximo conteúdo para manter clareza ou confiança"],"integrity_risks":["confundir permanência, pagamento ou conclusão com transformação","criar hierarquias simbólicas entre iniciados e não iniciados","ampliar complexidade para aumentar dependência","usar exposição de vulnerabilidade como requisito de pertencimento","reter pessoas em percursos que já não lhes servem","apresentar uma metodologia como resposta total","desconsiderar limites de tempo, acesso, saúde ou contexto profissional","reduzir autonomia em nome de acompanhamento"],"results":[{"level":"Audiência","signal":"A pessoa integra linguagem, conceitos e prática, transfere princípios entre contextos e produz distinções próprias.","indicator":"Sínteses autorais, aplicação adaptada, perguntas mais precisas, uso em novos contextos, qualidade da reflexão e menor dependência de instruções.","window":"Média a longa.","limitation":"Fluência verbal, tempo de permanência e conclusão não comprovam incorporação."},{"level":"Jornada","signal":"O percurso sustenta maturação, contribuição, autonomia e novas camadas de investigação.","indicator":"Retomadas qualificadas, evolução dos casos, feedback utilizado, participação entre pares, sínteses periódicas e continuidade intencional.","window":"Média a longa.","limitation":"Engajamento pode decorrer de vínculo, hábito, pressão do grupo ou incentivo."},{"level":"Negócio","signal":"A Bee constrói continuidade qualificada e condições para formações, comunidades e Jornadas Avançadas coerentes com a maturidade da audiência.","indicator":"Retenção com participação, conclusão significativa, demanda mais qualificada, progressão responsável e contribuição à comunidade.","window":"Média a longa.","limitation":"Receita, renovação ou acesso a ofertas avançadas não demonstram, isoladamente, Aprofundamento."}],"learning_questions":["Qual cadência favorece continuidade sem produzir sobrecarga?","Que combinação entre encontro, prática e intervalo aumenta integração?","Como organizar camadas de complexidade sem criar pré-requisitos artificiais?","O que pode ser autoguiado e o que requer facilitação ou feedback?","Quando a troca entre pares amplia compreensão e quando gera ruído ou conformidade?","Que sinais indicam síntese, transferência e autonomia, e não apenas familiaridade?","Em que momento uma sequência precisa revisitar fundamentos em vez de avançar?","Como preservar flexibilidade para pessoas com agendas apertadas sem dissolver continuidade?"],"confounders":["pagamento realizado ou custo irrecuperável","desejo de obter certificação ou status","exclusividade de acesso","carisma ou autoridade de Marcos ou de outro facilitador","pressão, pertencimento ou conformidade do grupo","disponibilidade desigual de tempo","repertório anterior e seleção de participantes mais preparados","qualidade geral do produto, da plataforma ou da facilitação","familiaridade com a linguagem sem mudança de prática","sobreposição com Conexão, Experimentação ou resultados externos"],"hypotheses":[{"hypothesis":"Uma sequência espaçada com prática e reflexão produz mais integração do que uma única peça intensiva com conteúdo equivalente.","variable":"Espaçamento e ciclos de prática.","control":"Tema, carga total e público comparáveis.","signal":"Mais transferência, sínteses próprias e retomadas qualificadas.","decision":"Padrão repetido em ciclos comparáveis, sem queda desproporcional de conclusão."},{"hypothesis":"Organizar princípio, caso, aplicação e síntese produz mais capacidade do que oferecer apenas explicação teórica.","variable":"Presença das quatro operações.","control":"Mesmo princípio, canal e janela.","signal":"Aplicações mais adaptadas e justificativas mais conscientes.","decision":"Evidência recorrente de transferência, não apenas satisfação ou memorização."},{"hypothesis":"Diálogo entre pares acompanhado de feedback amplia aprendizagem relacional em comparação com percurso exclusivamente individual, sem aumentar dependência.","variable":"Troca entre pares e feedback.","control":"Mesma prática, duração e conteúdo-base.","signal":"Maior diversidade de leitura, qualidade de reflexão e autonomia posterior.","decision":"Ganho consistente sem pressão de conformidade ou necessidade permanente do grupo."}],"transitions":["Aprofundamento → Reconhecimento: quando uma investigação madura torna visível uma realidade antes não percebida","Aprofundamento → Identificação: quando novas camadas ajudam a pessoa a se localizar de forma mais precisa","Aprofundamento → Conexão: quando a complexidade compartilhada pede confiança, reciprocidade ou comunidade renovada","Aprofundamento → Experimentação: quando uma distinção precisa voltar ao contato vivido em outro contexto","Aprofundamento → Aprofundamento: quando novas aplicações, sínteses ou camadas precisam ser sustentadas antes de outro movimento"],"short":"Eu quero ir além.","purpose":"Transformar interesse em desejo de compreender e viver mais profundamente aquela abordagem.","effect":"Quero ir além. Quero compreender e viver isso.","color":"#8562B8","paths":["Educação mais estruturada","6 Dimensões","Conteúdos da Masterclass / FLS","Cortes de aulas / conversas","Cases aprofundados","Bastidores de experiências Bee"],"editorials":["diagnostico-sistemico","case-anonimizado","bastidor-da-bee","trecho-livro-contextualizado"]}'::jsonb, 'docs/acj/ACJ-05_Aprofundamento_v0.1.md', now())
